// Function to remove duplicates from a sorted linked list
struct Node* removeDuplicates(struct Node* head) {
 struct Node* current = head;
 struct Node* temp;

 if (head == NULL)
 return head;

 while (current->next != NULL) {
 if (current->data == current->next->data) // Duplicate found: skip the next node
 {
 temp = current->next;
 current->next = current->next->next;
 free(temp); // free memory of removed node
 } else {
 current = current->next; // Move forward
 }
 }
 return head;
}
```

**A) Pseudocode for execution order:**

```cpp
void RoundRobin(Process* head, int timeQuantum) {
 Process* ptr = head;
 int allCompleted;
 do {
 allCompleted = 1; // assume all processes finished
 Process* start = ptr; // mark start of this cycle
 do {
 if(ptr->remainingTime > 0) {
 allCompleted = 0; // there is at least one process left
 // Execute process for min(timeQuantum, remainingTime)
 if(ptr->remainingTime > timeQuantum) {
 print(ptr->name, "executes for", timeQuantum, "units");
 ptr->remainingTime -= timeQuantum;
 } 
 else {
 print(ptr->name, "executes for", ptr->remainingTime, "units (finishes)");
 ptr->remainingTime = 0;
 }
 print("Remaining time of", ptr->name, "=", ptr->remainingTime);
 }
 ptr = ptr->next; // move to next process
 } while(ptr != start); // full cycle completed
 } while(!allCompleted); // repeat until all processes finished
}

```

