Process* RemoveProcess(Process* head, Process* toRemove) {
 if(head == NULL) return NULL; // Only one node in the list
 if(head == toRemove && head->next == head) {
 free(toRemove);
 return NULL;
 }
 Process* prev = head; // Find previous node
 while(prev->next != toRemove)
 prev = prev->next; // Remove node
 prev->next = toRemove->next; 
 if(toRemove == head) // Update head if needed
 head = toRemove->next;
 free(toRemove);
 return head;
}
```

