PolyNode* SubtractPolynomials(PolyNode* P1, PolyNode* P2) {
 PolyNode* resultHead = NULL; // head of result list
 PolyNode* resultTail = NULL;
 while(P1 != NULL || P2 != NULL) {
 PolyNode* newNode = (PolyNode*)malloc(sizeof(PolyNode));
 if(P1 != NULL && P2 != NULL) {
 if(P1->exp == P2->exp) {
 newNode->coeff = P1->coeff - P2->coeff;
 newNode->exp = P1->exp;
 P1 = P1->next;
 P2 = P2->next;
 } 
 else if(P1->exp > P2->exp) {
 newNode->coeff = P1->coeff;
 newNode->exp = P1->exp;
 P1 = P1->next;
 } 
 else { // P2->exp > P1->exp
 newNode->coeff = -P2->coeff; // subtracting => negate
 newNode->exp = P2->exp;
 P2 = P2->next;
 }
 } 
 else if(P1 != NULL) { // remaining P1 terms
 newNode->coeff = P1->coeff;
 newNode->exp = P1->exp;
 P1 = P1->next;
 } 
 else { // remaining P2 terms
 newNode->coeff = -P2->coeff;
 newNode->exp = P2->exp;
 P2 = P2->next;
 }
 newNode->next = NULL;
 if(resultHead == NULL) { // Append to result list
 resultHead = resultTail = newNode;
 } else {
 resultTail->next = newNode;
 resultTail = newNode;
 }
 }
 return resultHead;
}
```

