// Function to return precedence of operators
int precedence(char op) {
 if (op == '^') return 3;
 else if (op == '*' || op == '/') return 2;
 else if (op == '+' || op == '-') return 1;
 else return 0;
}

InfixToPostfix(string infix) { // Function to convert infix to postfix
 Stack s; // stack to hold operators
 string postfix = ""; // output expression
 char ch;
 for (i = 0; i < length(infix); i++) {
 ch = infix[i];
 if (ch is operand) {
 // directly add operand to postfix
 postfix = postfix + ch;
 }
 else if (ch == '(') {
 push(s, ch);
 }
 else if (ch == ')') {
 while (!isEmpty(s) && top(s) != '(') {
 postfix = postfix + pop(s);
 }
 pop(s); // discard '('
 }
 else if (ch is operator) {
 while (!isEmpty(s) && precedence(top(s)) >= precedence(ch)) {
 postfix = postfix + pop(s);
 }
 push(s, ch);
 }
 }
 while (!isEmpty(s)) { // pop any remaining operators
 postfix = postfix + pop(s);
 }
 return postfix;
}
